import React from 'react';
import type { FC } from 'react';
import { match } from 'variant';
import { z } from 'zod';
import { getWixConfigFilePath } from '@wix/cli-core-definitions';
import { readJson, writeJson } from '@wix/cli-fs';
import { Alert, useAsync } from '@wix/cli-ui-kit';
import { useEditorMigrationClient } from '@wix/editor-migration-client';
import { useProjectModel } from '../../model.js';
import { resolveParentDeploymentTarget } from '../../migration/parent-deployment-target.js';
import type { ParentTarget } from '../../migration/parent-deployment-target.js';
import { runWixCommand } from '../../migration/run-wix-command.js';

async function publish() {
  await runWixCommand('build');
  await runWixCommand('release');
}

export const FinalizeMigrationCommand: FC<{
  expected: ParentTarget;
  operatorTarget?: ParentTarget;
  onPublishing: (publishing: Promise<void>) => void;
}> = ({ expected, operatorTarget, onPublishing }) => {
  const { model } = useProjectModel();
  const editorMigrationClient = useEditorMigrationClient(expected.siteId);

  const { status } = useAsync(async ({ signal }) => {
    const { target, isAlreadyFinalized } = await resolveParentDeploymentTarget(
      editorMigrationClient,
      expected,
      operatorTarget
    );
    const configPath = getWixConfigFilePath(model.projectFolder);
    const config = z.record(z.unknown()).parse(await readJson(configPath));
    await writeJson(
      configPath,
      { ...config, appId: target.appId, siteId: target.siteId },
      { spaces: 2 }
    );
    if (!isAlreadyFinalized && !signal.aborted) {
      const publishing = publish();
      onPublishing(publishing);
      await publishing;
    }
    return { configPath, isAlreadyFinalized };
  }, []);

  return match(status, {
    // No spinner: `wix build` and `wix release` write to the terminal
    // directly, and redrawing it would erase the end of their output.
    Loading: () => null,
    Success: ({ result: { configPath, isAlreadyFinalized } }) =>
      isAlreadyFinalized ? (
        <Alert type="success">
          This migration is already finalized, and {configPath} points at the
          parent app and site. To publish changes, run `wix build` and `wix
          release`.
        </Alert>
      ) : (
        <Alert type="success">
          Finalized the migration. {configPath} points at the parent app and
          site, and the parent site is published.
        </Alert>
      ),
    Error: () => null,
    NotRequested: () => null,
  });
};
